import{c as r,Q as a,j as o,m as d}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"新地图与探索","description":"","frontmatter":{},"headers":[],"relativePath":"b42/map.md","filePath":"b42/map.md","lastUpdated":1779619065000}'),l={name:"b42/map.md"};function e(i,t,s,n,h,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="新地图与探索" tabindex="-1">新地图与探索 <a class="header-anchor" href="#新地图与探索" aria-label="Permalink to &quot;新地图与探索&quot;">​</a></h1><p>B42 的地图在 B41 基础上做了<strong>垂直扩展</strong>（向上和向下）和<strong>水平扩展</strong>（向西和向外）。对 B41 老玩家来说，熟悉的城市仍在，但多了大量新区域。</p><hr><h2 id="新城镇与区域" tabindex="-1">新城镇与区域 <a class="header-anchor" href="#新城镇与区域" aria-label="Permalink to &quot;新城镇与区域&quot;">​</a></h2><h3 id="三大新城镇" tabindex="-1">三大新城镇 <a class="header-anchor" href="#三大新城镇" aria-label="Permalink to &quot;三大新城镇&quot;">​</a></h3><p>B42 在俄亥俄河沿岸向西扩展了地图，新增 3 个新城镇：</p><table tabindex="0"><thead><tr><th>城镇</th><th>特色</th><th>大小</th></tr></thead><tbody><tr><td><strong>新城镇 A</strong>（西部沿河）</td><td>沿河定居点，渔资源丰富</td><td>中小型</td></tr><tr><td><strong>新城镇 B</strong>（西部内陆）</td><td>农业区，农场多</td><td>中小型</td></tr><tr><td><strong>废弃西部小镇</strong></td><td>仿古旅游景点风格，独特氛围</td><td>小型</td></tr></tbody></table><blockquote><p>确切城镇名称待官方和社区进一步确认，以上基于更新日志描述。</p></blockquote><h3 id="新地标" tabindex="-1">新地标 <a class="header-anchor" href="#新地标" aria-label="Permalink to &quot;新地标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地点</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>孤儿院</strong></td><td>特殊建筑</td><td>独特的故事氛围，可能含特殊物资</td></tr><tr><td><strong>发电站</strong></td><td>工业</td><td>电力设施、工业材料</td></tr><tr><td><strong>高压电塔</strong></td><td>景观/导航</td><td>沿河分布，可用作地标导航</td></tr><tr><td><strong>河船</strong></td><td>特殊</td><td>俄亥俄河上的废弃船只</td></tr><tr><td><strong>路易斯维尔新区</strong></td><td>城市扩张</td><td>路易斯维尔新增多个城区</td></tr></tbody></table><h3 id="旧城镇翻新" tabindex="-1">旧城镇翻新 <a class="header-anchor" href="#旧城镇翻新" aria-label="Permalink to &quot;旧城镇翻新&quot;">​</a></h3><ul><li><strong>Muldraugh</strong> 等旧的城镇得到了细节翻新和环境增强</li><li>新增 430+ 手工制作的地图区块</li><li>世界物件更丰富（牙刷、泰迪熊、吉他等数百种装饰品）</li></ul><hr><h2 id="🏙️-摩天大楼-32-层极限" tabindex="-1">🏙️ 摩天大楼（32 层极限） <a class="header-anchor" href="#🏙️-摩天大楼-32-层极限" aria-label="Permalink to &quot;🏙️ 摩天大楼（32 层极限）&quot;">​</a></h2><p>B42 把建筑高度上限从 7 层提升到 <strong>32 层</strong>。路易斯维尔现在有了真正意义上的摩天大楼。</p><h3 id="探索策略" tabindex="-1">探索策略 <a class="header-anchor" href="#探索策略" aria-label="Permalink to &quot;探索策略&quot;">​</a></h3><ul><li>每层都是未知——你永远不知道下一层有什么样的办公室、会议室、走廊</li><li>楼道和楼梯间最危险——狭窄空间遭遇丧尸没有退路</li><li><strong>顶楼基地</strong>：安全性极高（丧尸不太可能爬 30 层），但每次外出回来都要爬很久</li><li>用**逃生绳（Sheet Rope）**从窗户快速下楼，但要确保绳子在</li></ul><div class="danger custom-block"><p class="custom-block-title">高楼风险</p><p>32 层的楼梯间如果有丧尸群，你无路可逃。进去之前确保有退路——逃生绳、足够体力、备用武器。</p></div><hr><h2 id="🏚️-地下室与地堡" tabindex="-1">🏚️ 地下室与地堡 <a class="header-anchor" href="#🏚️-地下室与地堡" aria-label="Permalink to &quot;🏚️ 地下室与地堡&quot;">​</a></h2><p>B42 世界首次向<strong>地下</strong>延伸。部分房屋会随机生成隐藏地下室。</p><h3 id="地下室类型" tabindex="-1">地下室类型 <a class="header-anchor" href="#地下室类型" aria-label="Permalink to &quot;地下室类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>内容</th></tr></thead><tbody><tr><td><strong>核避难所 (Fallout Shelter)</strong></td><td>物资齐全的地下掩体，可能含稀有物资</td></tr><tr><td><strong>恐慌室 (Panic Room)</strong></td><td>专门的安全房间，加固门+应急物资</td></tr><tr><td><strong>储物间</strong></td><td>普通地下储藏室，可能有食物和工具</td></tr><tr><td><strong>酒窖</strong></td><td>葡萄酒和其他酒类储存</td></tr><tr><td><strong>&quot;特殊&quot;地下室</strong></td><td>古怪/恐怖主题的隐藏房间</td></tr></tbody></table><h3 id="进入方式" tabindex="-1">进入方式 <a class="header-anchor" href="#进入方式" aria-label="Permalink to &quot;进入方式&quot;">​</a></h3><ul><li>通过壁橱、地板上的<strong>暗门 (Trap Door)</strong> 进入</li><li>不一定每栋房子都有——可以在沙盒设置中调整出现频率</li><li>地下室窗口极少——完全的黑暗环境</li></ul><div class="danger custom-block"><p class="custom-block-title">地下室生存法则</p><p>地下室没有窗户、漆黑一片、只有一个出入口。进去前确保：</p><ol><li>手电筒 + 备用电池</li><li>清理了楼上所有丧尸（免得被堵死出口）</li><li>随时准备丢闪光弹或火把照明</li></ol></div><hr><h2 id="🌲-无限荒野" tabindex="-1">🌲 无限荒野 <a class="header-anchor" href="#🌲-无限荒野" aria-label="Permalink to &quot;🌲 无限荒野&quot;">​</a></h2><p>地图边界外的&quot;隐形墙&quot;被<strong>程序化生成的荒野</strong>替代了。</p><ul><li>地图边界外生成无限的森林、河流、丘陵地形</li><li>支持真正的<strong>原始生存</strong>玩法——远离文明，完全自给自足</li><li>沙盒选项中可选择<strong>纯荒野世界</strong>（完全没有城镇和建筑）</li><li>对于游牧/猎人角色来说，世界现在&quot;无限大&quot;</li></ul><hr><h2 id="📍-出生点变更" tabindex="-1">📍 出生点变更 <a class="header-anchor" href="#📍-出生点变更" aria-label="Permalink to &quot;📍 出生点变更&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Echo Creek 不再作为出生点</p><p>B42.16 开始，Echo Creek 不再是可选的出生地点。它仍然存在，可以作为目的地前往，但不能在这里出生。</p></div><p>B41 的出生城镇（Rosewood、Riverside、Muldraugh、West Point）继续保留为出生选项。</p><hr><h2 id="🗺️-对-b41-玩家的导航建议" tabindex="-1">🗺️ 对 B41 玩家的导航建议 <a class="header-anchor" href="#🗺️-对-b41-玩家的导航建议" aria-label="Permalink to &quot;🗺️ 对 B41 玩家的导航建议&quot;">​</a></h2><ol><li><strong>旧地图仍然有用</strong>——熟悉的主要道路和城镇布局没变</li><li><strong>向西探索新区域</strong>——俄亥俄河现在是西部新边界</li><li><strong>高楼是新的终极目标</strong>——后期探索路易斯维尔的摩天楼</li><li><strong>地下室刷在旧房子里</strong>——不要忽略你&quot;熟悉&quot;的建筑物，检查壁橱！</li></ol>',37)])])}const b=r(l,[["render",e]]);export{u as __pageData,b as default};
